// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { BellRingIcon, PauseIcon, PlayIcon, RotateCcwIcon, XIcon } from 'lucide-react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  COUNTDOWN_MS,
  COUNTDOWN_NOTICE,
  LABEL,
  PHASES,
  PICKED,
  POMODORO,
  POMODORO_NOTICE,
  PRESETS,
  TICK,
  formatClock,
} from './script'

const PANEL = 252
const WORK_MS = POMODORO.workMin * 60_000
const BREAK_MS = POMODORO.shortBreakMin * 60_000

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const tick = (name: string, from: number, seconds: number) => {
    const proxy = { ms: from }
    const el = q(name)
    tl.to(proxy, {
      ms: from - seconds * 1000,
      duration: seconds,
      ease: 'none',
      immediateRender: false,
      onUpdate: () => {
        el.textContent = formatClock(proxy.ms)
      },
    })
  }
  const later = (minutes: number) => {
    tl.set(q('later-text'), { text: `${minutes} minutes later` })
    tl.fromTo(
      q('later'),
      { opacity: 0, scale: 0.9 },
      { opacity: 1, scale: 1, duration: 0.3, ease: 'back.out(2)', immediateRender: false },
    )
    tl.to(q('later'), { opacity: 0, duration: 0.3 }, '+=0.7')
  }
  const notice = (n: { time: string; title: string; message: string }) => {
    tl.set(q('n-time'), { text: n.time })
    tl.set(q('n-title'), { text: n.title })
    tl.set(q('n-message'), { text: n.message })
    tl.fromTo(
      q('overlay'),
      { opacity: 0, x: 24 },
      { opacity: 1, x: 0, duration: 0.4, ease: 'power3.out', immediateRender: false },
    )
    tl.fromTo(
      q('n-ring'),
      { scale: 1, opacity: 0.6 },
      { scale: 1.6, opacity: 0, duration: 0.9, ease: 'power2.out', immediateRender: false },
      '<0.2',
    )
  }
  const primary = (name: string, running: boolean) => {
    tl.set(q(`${name}-start`), { opacity: running ? 0 : 1 })
    tl.set(q(`${name}-pause`), { opacity: running ? 1 : 0 }, '<')
  }

  step(0)
  move(`preset-${PICKED}`, { at: 0.2 })
  click(`preset-${PICKED}`)
  tl.to(
    qa('preset'),
    { backgroundColor: 'rgba(255,255,255,0)', color: 'rgba(212,212,216,1)', duration: 0.15 },
    '<',
  )
  tl.to(
    q(`preset-${PICKED}`),
    { backgroundColor: 'var(--accent)', color: 'rgba(10,10,14,1)', duration: 0.15 },
    '<',
  )
  tl.set(q('cd-min'), { text: String(PRESETS[PICKED]) }, '<')
  tl.set(q('cd-clock'), { text: formatClock(COUNTDOWN_MS) }, '<')
  move('cd-label', { ax: 0.2 })
  click('cd-label')
  tl.to(q('cd-ph'), { opacity: 0, duration: 0.1 }, '<')
  type('cd-label-text', LABEL, { speed: 0.03 })
  move('cd-start')
  click('cd-start')
  primary('cd', true)
  tl.to(qa('cd-lock'), { opacity: 0.5, duration: 0.2 }, '<')
  tl.to(q('cd-status'), { opacity: 1, duration: 0.2 }, '<')
  tick('cd-clock', COUNTDOWN_MS, TICK)

  step(1, '+=0.2')
  move('page-body', { at: '<' })
  tl.to(q('side-panel'), { width: 0, duration: 0.5, ease: 'power2.inOut' }, '<')
  later(PRESETS[PICKED])
  notice(COUNTDOWN_NOTICE)

  step(2, '+=1')
  move('n-close')
  click('n-close')
  tl.to(q('overlay'), { opacity: 0, x: 24, duration: 0.25 }, '<')
  tl.set(q('cd-clock'), { text: formatClock(0) }, '<')
  tl.to(q('side-panel'), { width: PANEL, duration: 0.5, ease: 'power2.inOut' }, '<0.1')
  move('tab-2', { at: '+=0.1' })
  click('tab-2')
  tl.to(
    qa('tab'),
    { backgroundColor: 'rgba(255,255,255,0)', color: 'rgba(161,161,170,1)', duration: 0.15 },
    '<',
  )
  tl.to(
    q('tab-2'),
    { backgroundColor: 'rgba(255,255,255,0.1)', color: 'rgba(250,250,250,1)', duration: 0.15 },
    '<',
  )
  tl.to(q('view-countdown'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(q('view-pomodoro'), { opacity: 1, duration: 0.2 }, '<0.1')
  move('po-start')
  click('po-start')
  primary('po', true)
  tl.to(qa('po-lock'), { opacity: 0.5, duration: 0.2 }, '<')
  tl.set(q('po-status-text'), { text: `Running in the background · ${PHASES[0]}` }, '<')
  tl.to(q('po-status'), { opacity: 1, duration: 0.2 }, '<')
  tick('po-clock', WORK_MS, 2)
  move('page-body')
  later(POMODORO.workMin)
  notice(POMODORO_NOTICE)
  tl.to(
    qa('phase'),
    { backgroundColor: 'rgba(255,255,255,0)', color: 'rgba(212,212,216,1)', duration: 0.15 },
    '<',
  )
  tl.to(
    q('phase-1'),
    { backgroundColor: 'var(--accent)', color: 'rgba(10,10,14,1)', duration: 0.15 },
    '<',
  )
  tl.set(q('po-status-text'), { text: `Running in the background · ${PHASES[1]}` }, '<')
  tick('po-clock', BREAK_MS, 2)
  cursorOut('<')
  final('+=0.2')
  wait(1.4)

  tl.set(
    [
      q('overlay'),
      q('later'),
      q('view-pomodoro'),
      q('cd-status'),
      q('po-status'),
      q('cd-pause'),
      q('po-pause'),
    ],
    { opacity: 0 },
    0,
  )
  tl.set(
    [
      q('view-countdown'),
      q('cd-ph'),
      q('cd-start'),
      q('po-start'),
      ...qa('cd-lock'),
      ...qa('po-lock'),
    ],
    { opacity: 1 },
    0,
  )
  tl.set(q('side-panel'), { width: PANEL }, 0)
  tl.set(q('cd-clock'), { text: formatClock(5 * 60_000) }, 0)
  tl.set(q('po-clock'), { text: formatClock(WORK_MS) }, 0)
  tl.set(q('cd-min'), { text: '5' }, 0)
  tl.set(q('cd-label-text'), { text: '' }, 0)
}

function Field({
  label,
  value,
  d,
  lock,
}: {
  label: string
  value: string
  d?: string
  lock: string
}) {
  return (
    <span data-d={lock} className="min-w-0 flex-1">
      <span className="block text-center text-[7.5px] font-medium text-muted">{label}</span>
      <span className="mt-0.5 flex h-[22px] items-center justify-center rounded-md border border-line-strong bg-canvas/80 font-mono text-[10px] text-ink">
        <span data-d={d}>{value}</span>
      </span>
    </span>
  )
}

function Actions({ name }: { name: string }) {
  return (
    <span className="grid grid-cols-2 gap-1.5 text-[9.5px]">
      <span className="relative h-6">
        <span
          data-d={`${name}-start`}
          className="absolute inset-0 flex items-center justify-center gap-1 rounded-md bg-[var(--accent)] font-medium text-canvas"
        >
          <PlayIcon className="size-3" /> Start
        </span>
        <span
          data-d={`${name}-pause`}
          className="absolute inset-0 flex items-center justify-center gap-1 rounded-md border border-line-strong text-ink opacity-0"
        >
          <PauseIcon className="size-3" /> Pause
        </span>
      </span>
      <span className="flex h-6 items-center justify-center gap-1 text-ink-soft">
        <RotateCcwIcon className="size-3" /> Reset
      </span>
    </span>
  )
}

function Status({ d, text }: { d: string; text?: string }) {
  return (
    <p
      data-d={d}
      className="flex items-center justify-center gap-1.5 text-[8.5px] text-muted opacity-0"
    >
      <span className="size-1.5 rounded-full bg-[var(--accent)]" />
      <span data-d={`${d}-text`} className="truncate">
        {text}
      </span>
    </p>
  )
}

function Countdown() {
  return (
    <div data-d="view-countdown" className="absolute inset-0 flex flex-col gap-1.5">
      <div data-d="cd-lock" className="grid grid-cols-4 gap-1">
        {PRESETS.map((minutes, index) => (
          <span
            key={minutes}
            data-d={`preset preset-${index}`}
            className="flex h-5 items-center justify-center rounded-md border border-line-strong text-[8.5px] text-ink-soft"
          >
            {minutes} min
          </span>
        ))}
      </div>
      <div className="flex items-end gap-1">
        <Field label="Hours" value="0" lock="cd-lock" />
        <span className="pb-1 text-muted">:</span>
        <Field label="Minutes" value="5" d="cd-min" lock="cd-lock" />
        <span className="pb-1 text-muted">:</span>
        <Field label="Seconds" value="0" lock="cd-lock" />
      </div>
      <span data-d="cd-lock">
        <span className="block text-[7.5px] font-medium text-muted">Label</span>
        <span
          data-d="cd-label"
          className="relative mt-0.5 flex h-[22px] items-center rounded-md border border-line-strong bg-canvas/80 px-2 text-[9.5px] text-ink"
        >
          <span data-d="cd-ph" className="absolute left-2 text-muted">
            What is this timer for?
          </span>
          <span data-d="cd-label-text" className="truncate" />
        </span>
      </span>
      <p
        data-d="cd-clock"
        className="pt-1 text-center font-mono text-[26px] font-semibold leading-none tabular-nums text-ink"
      >
        {formatClock(5 * 60_000)}
      </p>
      <span className="h-1 rounded-full bg-white/[0.08]" />
      <Status d="cd-status" text={`Running in the background · ${LABEL}`} />
      <Actions name="cd" />
      <p className="text-center text-[7.5px] leading-snug text-muted">
        Keeps running if you close this panel. A popup appears on the page when it finishes.
      </p>
    </div>
  )
}

function Pomodoro() {
  return (
    <div data-d="view-pomodoro" className="absolute inset-0 flex flex-col gap-1.5 opacity-0">
      <div className="grid grid-cols-3 gap-1">
        {PHASES.map((phase, index) => (
          <span
            key={phase}
            data-d={`phase phase-${index}`}
            className={`flex h-5 items-center justify-center rounded-md border border-line-strong text-[8.5px] ${index === 0 ? 'bg-[var(--accent)] text-canvas' : 'text-ink-soft'}`}
          >
            {phase}
          </span>
        ))}
      </div>
      <p className="text-center text-[8.5px] text-muted">Round 1 of {POMODORO.roundsPerSet}</p>
      <div className="grid grid-cols-2 gap-x-1.5 gap-y-1">
        <Field label="Focus (min)" value={String(POMODORO.workMin)} lock="po-lock" />
        <Field label="Short (min)" value={String(POMODORO.shortBreakMin)} lock="po-lock" />
        <Field label="Long (min)" value={String(POMODORO.longBreakMin)} lock="po-lock" />
        <Field label="Rounds" value={String(POMODORO.roundsPerSet)} lock="po-lock" />
      </div>
      <span className="flex h-6 items-center justify-between rounded-md border border-line px-2 text-[8.5px] text-ink">
        Start the next phase automatically
        <span className="flex h-3 w-5 items-center justify-end rounded-full bg-[var(--accent)] px-0.5">
          <span className="size-2 rounded-full bg-canvas" />
        </span>
      </span>
      <p
        data-d="po-clock"
        className="text-center font-mono text-[26px] font-semibold leading-none tabular-nums text-ink"
      >
        {formatClock(WORK_MS)}
      </p>
      <span className="h-1 rounded-full bg-white/[0.08]" />
      <Status d="po-status" />
      <Actions name="po" />
    </div>
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col" style={{ width: PANEL }}>
      <DockHeader />
      <div className="flex min-h-0 flex-1 flex-col gap-1.5 p-2">
        <div className="grid grid-cols-3 gap-0.5 rounded-md bg-white/[0.04] p-0.5">
          {['Countdown', 'Stopwatch', 'Pomodoro'].map((label, index) => (
            <span
              key={label}
              data-d={`tab tab-${index}`}
              className={`rounded py-1 text-center text-[9px] ${index === 0 ? 'bg-white/10 text-ink' : 'text-muted'}`}
            >
              {label}
            </span>
          ))}
        </div>
        <div className="relative min-h-0 flex-1">
          <Countdown />
          <Pomodoro />
        </div>
      </div>
    </div>
  )
}

function Page() {
  return (
    <div data-d="page-body" className="relative h-full bg-[#fafafa] px-4 pt-3 text-[#111]">
      <p className="text-[8px] font-semibold uppercase tracking-[0.2em] text-[#2563eb]">
        Northwind Docs
      </p>
      <h3 className="mt-1 text-[15px] font-bold tracking-tight">Release notes · v2.4</h3>
      <p className="mt-2 text-[9px] font-semibold text-[#334155]">What’s new</p>
      <div className="mt-1.5 space-y-1.5">
        {[92, 84, 96, 70, 88, 64, 90, 76].map((width, index) => (
          <span
            key={index}
            className="block h-1.5 rounded-full bg-black/[0.08]"
            style={{ width: `${width}%` }}
          />
        ))}
      </div>
      <p className="mt-3 text-[9px] font-semibold text-[#334155]">Fixes</p>
      <div className="mt-1.5 space-y-1.5">
        {[80, 94, 58].map((width, index) => (
          <span
            key={index}
            className="block h-1.5 rounded-full bg-black/[0.08]"
            style={{ width: `${width}%` }}
          />
        ))}
      </div>
      <div
        data-d="later"
        className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full bg-[#111]/85 px-3 py-1.5 text-[10px] font-medium text-white opacity-0"
      >
        <span data-d="later-text" />
      </div>
      <div
        data-d="overlay"
        className="absolute right-3 top-3 grid w-[min(300px,calc(100%-24px))] grid-cols-[auto_1fr_auto] items-start gap-2.5 overflow-hidden rounded-xl border border-[#2a3133] bg-[#1c2022] p-2.5 pl-3 text-[#f8fafc] opacity-0 shadow-2xl"
      >
        <span className="absolute inset-y-0 left-0 w-[3px] bg-[var(--accent)]" />
        <span className="relative flex size-8 items-center justify-center rounded-lg bg-[var(--accent)]/15 text-[var(--accent)]">
          <BellRingIcon className="size-4" />
          <span
            data-d="n-ring"
            className="absolute inset-0 rounded-lg ring-2 ring-[var(--accent)]/50"
          />
        </span>
        <span className="min-w-0">
          <span className="flex items-center gap-1 text-[8.5px] text-[#a1a1aa]">
            One Panel · Timer <span className="size-[3px] rounded-full bg-current" />{' '}
            <span data-d="n-time" />
          </span>
          <span data-d="n-title" className="mt-0.5 block text-[11px] font-semibold" />
          <span data-d="n-message" className="block text-[9.5px] text-[#a1a1aa]" />
        </span>
        <span
          data-d="n-close"
          className="flex size-6 items-center justify-center rounded-md text-[#a1a1aa]"
        >
          <XIcon className="size-3.5" />
        </span>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Timer starting a ${PRESETS[PICKED]} minute countdown labelled "${LABEL}", finishing on the page after the panel is closed, then running a Pomodoro focus round that hands off to a short break`}
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://docs.northwind.dev/releases/2.4"
        panelWidth={PANEL}
        panel={<Panel />}
      >
        <Page />
      </BrowserChrome>
    </DemoStage>
  )
}
